import subprocess, sys

sys.path.insert(0, '_tools')
import kb_mcp

def handle(msg_id, method, params=None):
    msg = {'jsonrpc': '2.0', 'id': msg_id, 'method': method}
    if params is not None:
        msg['params'] = params
    return kb_mcp.handle(msg)['result']

def call(arguments):
    res = handle(2, 'tools/call', {'name': 'kb_tools', 'arguments': arguments})
    return res['isError'], res['content'][0]['text']

def kbtools(*args):
    return subprocess.run([sys.executable, '_tools/kbtools.py', *args], capture_output=True, text=True).stdout

problems = []
tool = next((t for t in handle(1, 'tools/list')['tools'] if t['name'] == 'kb_tools'), None)
if not tool:
    print('kb_tools is not listed by tools/list')
    sys.exit(1)
schema = tool['inputSchema']
if not (tool['annotations']['readOnlyHint'] is True and 'need' in schema['properties'] and 'need' not in schema.get('required', [])):
    problems.append('kb_tools is not read-only with an optional need')
need = 'what a sprint item cost in tokens and dollars'
for arguments, want in (({'need': need}, kbtools(need)), ({}, kbtools())):
    err, text = call(arguments)
    lines = [l for l in want.splitlines() if l.strip()]
    if err or not lines or not all(l in text for l in lines):
        problems.append(f'kb_tools {arguments} does not return the lines of kbtools.py: {err} {text[:120]!r}')
if 'backlog.py' not in call({'need': need})[1]:
    problems.append('the answer for a sprint cost need does not name backlog.py')
if call({'need': need, 'bogus': 1})[0] is not True:
    problems.append('an unknown argument is not refused')  # a closed schema
print('kb_tools listed;', problems or 'read-only, need optional, text holds the lines of kbtools.py for a need and for none')
sys.exit(1 if problems else 0)
